 "content": "def transform(grid):
    """Fill each framed zero-mask with the matching colored object on the right."""
    if not grid:
        return []
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    # The first frame occupies the initial run of its background color.
    frame_w = 0
    while frame_w < w and grid[0][frame_w] == bg:
        frame_w += 1
    if frame_w == 0:
        return [row[:] for row in grid]

    # Extract each right-hand colored object's shape within its bounding box.
    objects = {}
    for color in {v for row in grid for v in row if v not in (0, bg)}:
        cells = [(r, c) for r in range(h) for c in range(frame_w, w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, _ in cells); r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells); c1 = max(c for _, c in cells)
        objects[color] = [[grid[r][c] == color for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]

    # Full-background rows in the frame are horizontal panel boundaries.
    boundaries = [r for r in range(h) if all(grid[r][c] == bg for c in range(frame_w))]
    out = [row[:frame_w] for row in grid]
    for top, bottom in zip(boundaries, boundaries[1:]):
        if bottom <= top + 1:
            continue
        mask = [[grid[r][c] == 0 for c in range(frame_w)] for r in range(top + 1, bottom)]
        match = next((color for color, shape in objects.items() if shape == mask), None)
        if match is not None:
            for rr, rowmask in enumerate(mask, start=top + 1):
                for c, is_hole in enumerate(rowmask):
                    if is_hole:
                        out[rr][c] = match
    return out
